KEYS = "touch_input_new_profile touch_input_rebind touch_input_all_bindings touch_input_touches_format touch_input_hint_drag chat_preview_title chat_preview_description chat_preview_sample_1 chat_preview_sample_2 chat_preview_sample_3 chat_preset_default chat_preset_readable chat_preset_subtle chat_preset_large chat_section_text chat_section_shadow chat_section_background chat_section_button touch_input_source_controller touch_input_source_overlay touch_input_overlay_message touch_input_add_overlay_button button_touch button_touch_format touch_input_overlay_button_format".split()
R = sys.argv[1] if len(sys.argv) > 1 else "src/android/app/src/main/res"
LOC=sorted(d for d in os.listdir(R) if d.startswith('values-'))
def esc(t):
    t=t.replace('\\\'',"'").replace("'","\\'")
    return t.replace('&','&amp;') if '&' in t and '&amp;' not in t else t
ok=0
for d in LOC:
    code=d[len('values-'):]
    if code=='b+en+GB': continue
    tr=T.get(code)
    if not tr: print('MISSING',code); continue
    assert len(tr)==25,(code,len(tr))
    f=os.path.join(R,d,'strings.xml'); s=open(f,encoding='utf-8').read()
    add=''
    for k,v in zip(KEYS,tr):
        if f'name="{k}"' in s: continue
        add+=f'    <string name="{k}">{esc(v)}</string>\n'
    if add:
        s=s.replace('</resources>','\n    <!-- Chat overlay and touch input additions -->\n'+add+'</resources>')
        open(f,'w',encoding='utf-8').write(s); ok+=1
print('updated',ok)
